"""Compute total monthly salaries per employee from the cleaning-service dataset.

Data cleaning applied:
- 5 employee IDs in the timesheet fail the PESEL checksum; each is a 2-3 digit
  typo of exactly one valid employee PESEL (next-closest is 7+ digits away),
  so they are corrected to that PESEL.
- performed_tasks lists with missing brackets are parsed by extracting the
  numeric task IDs; task IDs absent from tasks.csv are dropped.
- The bonus column equals the sum of task pays for 893/900 well-formed rows
  (the rest are negative bonuses on empty task lists), so the bonus is
  recomputed from the valid performed tasks.
- The salary_amount column is inconsistent with hours*rate+bonus in 990/1008
  rows and is ignored.
- Impossible dates (2025-04-31, 2025-06-31) have their day clamped to the
  last valid day of the month.

Billing periods: the earliest record (2025-03-04) is a Tuesday, so each
month's billing period starts on the first Tuesday of that calendar month
and ends the day before the first Tuesday of the next month.
"""

import csv
import datetime
import math
import re
from collections import defaultdict

DATA_DIR = "/app/dataset"


def pesel_valid(p: str) -> bool:
    if len(p) != 11 or not p.isdigit():
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    check = (10 - sum(int(a) * w for a, w in zip(p, weights)) % 10) % 10
    return check == int(p[10])


def parse_date(s: str) -> datetime.date:
    y, m, d = map(int, s.split("-"))
    while True:
        try:
            return datetime.date(y, m, d)
        except ValueError:
            d -= 1


def first_weekday_of_month(y: int, m: int, weekday: int) -> datetime.date:
    d = datetime.date(y, m, 1)
    return d + datetime.timedelta(days=(weekday - d.weekday()) % 7)


def answer() -> dict[str, list[int]]:
    with open(f"{DATA_DIR}/employees.csv", encoding="utf-8") as f:
        employees = list(csv.DictReader(f))
    with open(f"{DATA_DIR}/tasks.csv", encoding="utf-8") as f:
        tasks = list(csv.DictReader(f))
    with open(f"{DATA_DIR}/timesheet.csv", encoding="utf-8") as f:
        timesheet = list(csv.DictReader(f))

    rate = {e["PESEL"]: float(e["hourly_rate"]) for e in employees}
    task_pay = {t["task_id"]: float(t["pay_per_completion"]) for t in tasks}

    def fix_employee_id(eid: str) -> str | None:
        if eid in rate:
            return eid
        if not pesel_valid(eid):
            candidates = sorted(
                rate,
                key=lambda p: sum(1 for a, b in zip(p, eid) if a != b),
            )
            best = candidates[0]
            best_dist = sum(1 for a, b in zip(best, eid) if a != b)
            second_dist = sum(1 for a, b in zip(candidates[1], eid) if a != b)
            if best_dist <= 3 and second_dist > best_dist:
                return best
        return None

    dates = [parse_date(r["date"]) for r in timesheet]
    start_weekday = min(dates).weekday()

    def period_start(d: datetime.date) -> datetime.date:
        start = first_weekday_of_month(d.year, d.month, start_weekday)
        if d < start:
            prev_y, prev_m = (d.year, d.month - 1) if d.month > 1 else (d.year - 1, 12)
            start = first_weekday_of_month(prev_y, prev_m, start_weekday)
        return start

    totals: dict[str, dict[datetime.date, float]] = defaultdict(lambda: defaultdict(float))
    for row, d in zip(timesheet, dates):
        eid = fix_employee_id(row["employee_id"])
        if eid is None:
            continue
        try:
            hours = float(row["hours_worked"])
        except ValueError:
            continue
        if hours < 0:
            continue
        task_ids = re.findall(r"\d+", row["performed_tasks"])
        bonus = sum(task_pay[t] for t in task_ids if t in task_pay)
        totals[eid][period_start(d)] += hours * rate[eid] + bonus

    return {
        eid: [
            int(math.floor(v + 0.5))
            for _, v in sorted(months.items())
        ]
        for eid, months in totals.items()
    }


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

